//! Per-add invocation scheduler. An invocation races only its own workers.
use std::{sync::{Arc,Mutex,MutexGuard,TryLockError,mpsc,atomic::{AtomicBool,AtomicUsize,Ordering}},thread,time::{Duration,Instant}};
use serde_json::Value;
use super::{csdm_analysis::{Analyses,Claim},csdm_analysis_service as svc};
type Read= dyn Fn()->Result<Value,String>+Send+Sync;
type Process= dyn Fn(Claim,Value)->Result<(),String>+Send+Sync;
type Emit= dyn Fn(Value)->Result<(),String>+Send+Sync;
pub struct Scheduler {state:Arc<Mutex<Analyses>>, order:Arc<Mutex<()>>,read:Arc<Read>, process:Arc<Process>,emit:Arc<Emit>,admission:Mutex<()>,paused:AtomicBool,join_failed:AtomicBool,stopping:AtomicBool,invocations:AtomicUsize,workers:Mutex<Vec<thread::JoinHandle<()>>>,errors:Arc<Mutex<Vec<String>>>}
fn lock_until<'a,T>(m:&'a Mutex<T>,deadline:Instant,label:&str)->Result<MutexGuard<'a,T>,String>{loop{if Instant::now()>=deadline{return Err(format!("{label} shutdown unconfirmed"))}match m.try_lock(){Ok(g)=>return Ok(g),Err(TryLockError::Poisoned(_))=>return Err(format!("{label} poisoned; shutdown unconfirmed")),Err(TryLockError::WouldBlock)=>{if Instant::now()>=deadline{return Err(format!("{label} shutdown unconfirmed"))}thread::sleep(Duration::from_millis(5))}}}}
struct Invocation<'a>(&'a AtomicUsize);impl Drop for Invocation<'_>{fn drop(&mut self){self.0.fetch_sub(1,Ordering::AcqRel);}}
impl Scheduler{
 pub fn new(state:Arc<Mutex<Analyses>>,order:Arc<Mutex<()>>,read:impl Fn()->Result<Value,String>+Send+Sync+'static,process:impl Fn(Claim,Value)->Result<(),String>+Send+Sync+'static,emit:impl Fn(Value)->Result<(),String>+Send+Sync+'static)->Arc<Self>{Arc::new(Self{state,order,read:Arc::new(read),process:Arc::new(process),emit:Arc::new(emit),admission:Mutex::new(()),paused:AtomicBool::new(false),join_failed:AtomicBool::new(false),stopping:AtomicBool::new(false),invocations:AtomicUsize::new(0),workers:Mutex::new(Vec::new()),errors:Arc::new(Mutex::new(Vec::new()))})}
 /// Snapshot the same live owner, serialized with a complete claim batch.
 pub fn analysis_snapshot(&self,timeout:Duration)->Result<Vec<Value>,String>{let deadline=Instant::now()+timeout;let _permit=lock_until(&self.admission,deadline,"analysis snapshot admission")?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}let state=lock_until(&self.state,deadline,"analysis snapshot state")?;Ok(state.all())}
 pub fn add_renderer(self:&Arc<Self>,demos:Vec<Value>)->Result<(),String>{let permit=self.admission.lock().map_err(|_|"admission unavailable")?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}if self.paused.load(Ordering::Acquire){return Err("scheduler disconnected".into())}self.invocations.fetch_add(1,Ordering::AcqRel);let _invocation=Invocation(&self.invocations);let added=svc::ordered(&self.state,&self.order,|s|{let e=s.add(demos,None,None,||chrono::DateTime::<chrono::Utc>::from(std::time::SystemTime::now()).to_rfc3339_opts(chrono::SecondsFormat::Millis,true))?;Ok((e.is_some(),e))},&mut |e|(self.emit)(e)).map_err(|e|self.fatal(format!("renderer enqueue or delivery failed; queued state may remain: {e}")))?;drop(permit);if added{self.invoke_loop().map_err(|e|self.fatal(format!("renderer invocation failed; queued state may remain: {e}")))?}Ok(())}
 /// Serialize renderer removal with the complete synchronous refill batch.
 pub fn remove_renderer(self:&Arc<Self>,keys:Vec<String>,timeout:Duration)->Result<(),String>{let permit=lock_until(&self.admission,Instant::now()+timeout,"renderer removal admission").map_err(|e|format!("renderer removal could not acquire admission: {e}"))?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}if self.paused.load(Ordering::Acquire){return Err("scheduler disconnected".into())}self.invocations.fetch_add(1,Ordering::AcqRel);let _invocation=Invocation(&self.invocations);let result=svc::ordered(&self.state,&self.order,|s|{let refs:Vec<&str>=keys.iter().map(String::as_str).collect();s.remove(&refs);Ok(((),Some(serde_json::json!({"name":"demos-removed-from-analyses","payload":keys}))))},&mut |event|(self.emit)(event)).map_err(|e|self.fatal(format!("renderer removal or delivery failed; queue state may have changed: {e}")));drop(permit);result}
 fn fatal(&self,message:String)->String{self.stopping.store(true,Ordering::Release);if let Ok(mut errors)=self.errors.lock(){errors.push(message.clone())}message}
 /// Call from the authenticated, tracked CLI request; successful new work is
 /// scheduled asynchronously so the CLI reply does not await analysis.
 pub fn enqueue_cli(self:&Arc<Self>,id:&str,demos:Vec<Value>,positions:Option<bool>)->Result<(bool,bool),String>{let permit=self.admission.lock().map_err(|_|"admission unavailable")?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}if self.paused.load(Ordering::Acquire){return Err("scheduler disconnected".into())}self.invocations.fetch_add(1,Ordering::AcqRel);let _invocation=Invocation(&self.invocations);let result=svc::cli_enqueue(&self.state,&self.order,id,demos,positions,||chrono::DateTime::<chrono::Utc>::from(std::time::SystemTime::now()).to_rfc3339_opts(chrono::SecondsFormat::Millis,true),&mut |e|(self.emit)(e)).map_err(|e|self.fatal(format!("CLI enqueue or delivery failed; queued state may remain: {e}")))?;drop(permit);if result.0&&result.1{if let Err(e)=self.kick(){if e!="scheduler disconnected"{return Err(self.fatal(format!("CLI work enqueued but scheduler start failed: {e}")))}}}Ok(result)}
 /// Start a nonblocking, tracked invocation. Completion and all workers remain
 /// reachable through this owner until shutdown confirms quiescence.
 pub fn kick(self:&Arc<Self>)->Result<(),String>{let permit=self.admission.lock().map_err(|_|"admission unavailable")?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}if self.paused.load(Ordering::Acquire){return Err("scheduler disconnected".into())}let mut registry=self.workers.lock().map_err(|_|"worker registry unavailable")?;self.invocations.fetch_add(1,Ordering::AcqRel);let s=self.clone();let(go,ready)=mpsc::sync_channel::<()>(1);let job=thread::Builder::new().spawn(move||{let _invocation=Invocation(&s.invocations);if ready.recv().is_err(){return}if let Err(error)=s.invoke_loop(){if !error.starts_with("scheduler stopping"){if let Ok(mut errors)=s.errors.lock(){errors.push(format!("CLI invocation failed: {error}"))}s.stopping.store(true,Ordering::Release)}}});match job{Ok(worker)=>registry.push(worker),Err(e)=>{self.invocations.fetch_sub(1,Ordering::AcqRel);return Err(self.fatal(format!("CLI invocation spawn failed: {e}")))}}drop(registry);drop(permit);go.send(()).map_err(|_|self.fatal("CLI invocation start failed".into()))}
 /// Called in an already tracked request after a CLI add produced new work.
 pub fn invoke_added(self:&Arc<Self>)->Result<(),String>{let permit=self.admission.lock().map_err(|_|"admission unavailable")?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}if self.paused.load(Ordering::Acquire){return Err("scheduler disconnected".into())}self.invocations.fetch_add(1,Ordering::AcqRel);let _invocation=Invocation(&self.invocations);drop(permit);self.invoke_loop().map_err(|e|self.fatal(format!("CLI invocation failed; queued state may remain: {e}")))}
 fn invoke_loop(self:&Arc<Self>)->Result<(),String>{loop{if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}if self.paused.load(Ordering::Acquire){return Ok(())}let settings=(self.read)()?;let max=svc::concurrency_limit(&settings)?;let(tx,rx)=mpsc::channel::<()>();let mut started=0usize;let mut launch=Vec::new();let permit=self.admission.lock().map_err(|_|"admission unavailable")?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}if self.paused.load(Ordering::Acquire){return Ok(())}loop{let mut registry=self.workers.lock().map_err(|_|"worker registry unavailable before launch")?;while let Some(index)=registry.iter().position(|w|w.is_finished()){if registry.swap_remove(index).join().is_err(){self.join_failed.store(true,Ordering::Release);self.stopping.store(true,Ordering::Release);if let Ok(mut errors)=self.errors.lock(){errors.push("worker join failed; outcome unknown".into())}return Err("worker join failed; outcome unknown".into())}}let claim=svc::claim_and_start(&self.state,&self.order,max,&mut |e|(self.emit)(e))?;let Some(claim)=claim else{break};let id=claim.run_id;let s=self.clone();let settings=settings.clone();let done=tx.clone();let(go,ready)=mpsc::sync_channel::<()>(1);match thread::Builder::new().spawn(move||{if ready.recv().is_err(){if let Err(e)=svc::finish(&s.state,&s.order,id){if let Ok(mut errors)=s.errors.lock(){errors.push(format!("unstarted worker cleanup unconfirmed: {e}"))}s.stopping.store(true,Ordering::Release)}let _=done.send(());return}let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||(s.process)(claim,settings))).unwrap_or_else(|_|Err("analysis worker panicked; database outcome unknown".into()));if let Err(e)=result{if let Ok(mut errors)=s.errors.lock(){errors.push(e)}s.stopping.store(true,Ordering::Release)}if let Err(e)=svc::finish(&s.state,&s.order,id){if let Ok(mut errors)=s.errors.lock(){errors.push(format!("worker finalization unconfirmed: {e}"))}s.stopping.store(true,Ordering::Release)}let _=done.send(());}){Ok(worker)=>{registry.push(worker);launch.push(go);started+=1},Err(e)=>{self.stopping.store(true,Ordering::Release);let finish=svc::finish(&self.state,&self.order,id);let message=format!("worker spawn failed: {e}; claim cleanup: {finish:?}");if let Ok(mut errors)=self.errors.lock(){errors.push(message.clone())}return Err(message)}}}
 drop(permit);for go in launch{let _=go.send(());}drop(tx);if started==0{return Ok(())}loop{match rx.recv_timeout(Duration::from_millis(50)){Ok(())=>break,Err(mpsc::RecvTimeoutError::Timeout) if !self.stopping.load(Ordering::Acquire)=>{},Err(mpsc::RecvTimeoutError::Timeout)=>return Err("scheduler stopping; worker quiescence unconfirmed".into()),Err(mpsc::RecvTimeoutError::Disconnected)=>return Err("worker completion missing".into())}}if !self.state.lock().map_err(|_|"analysis state unavailable")?.has_pending(){return Ok(())}}
 }
 /// Stop admissions and wait for all tracked invocations and worker writers; preserve pending work.
 pub fn quiesce(&self,timeout:Duration)->Result<(),String>{self.paused.store(true,Ordering::Release);let deadline=Instant::now()+timeout;{let _permit=lock_until(&self.admission,deadline,"disconnect admission")?;}loop{let done=self.invocations.load(Ordering::Acquire)==0&&lock_until(&self.workers,deadline,"disconnect worker registry")?.iter().all(|w|w.is_finished());if done{break}if Instant::now()>=deadline{return Err("disconnect writers or invocations still active; outcome unconfirmed".into())}thread::sleep(Duration::from_millis(5))}let mut workers=lock_until(&self.workers,deadline,"disconnect worker registry")?;for worker in workers.drain(..){if worker.join().is_err(){self.join_failed.store(true,Ordering::Release);self.stopping.store(true,Ordering::Release)}}if self.join_failed.load(Ordering::Acquire){return Err("disconnect worker join failed; outcome unconfirmed".into())}let errors=lock_until(&self.errors,deadline,"disconnect errors")?;if !errors.is_empty(){return Err(format!("disconnect scheduler errors: {}",errors.join("; ")))}Ok(())}
 pub fn resume(self:&Arc<Self>,timeout:Duration)->Result<(),String>{let deadline=Instant::now()+timeout;let permit=lock_until(&self.admission,deadline,"resume admission")?;if self.stopping.load(Ordering::Acquire){return Err("scheduler stopping".into())}let pending=lock_until(&self.state,deadline,"resume state")?.has_pending();let mut go=None;if pending{let mut registry=lock_until(&self.workers,deadline,"resume worker registry")?;self.invocations.fetch_add(1,Ordering::AcqRel);let s=self.clone();let(tx,rx)=mpsc::sync_channel::<()>(1);match thread::Builder::new().spawn(move||{let _invocation=Invocation(&s.invocations);if rx.recv().is_err(){return}let admission=match s.admission.lock(){Ok(g)=>g,Err(_)=>{s.stopping.store(true,Ordering::Release);return}};drop(admission);if let Err(error)=s.invoke_loop(){if !error.starts_with("scheduler stopping"){if let Ok(mut errors)=s.errors.lock(){errors.push(format!("resumed invocation failed: {error}"))}s.stopping.store(true,Ordering::Release)}}}){Ok(worker)=>{registry.push(worker);go=Some(tx)},Err(e)=>{self.invocations.fetch_sub(1,Ordering::AcqRel);return Err(format!("resume spawn failed: {e}"))}}}if let Some(tx)=go{if tx.send(()).is_err(){return Err(self.fatal("resumed invocation start failed".into()))}}self.paused.store(false,Ordering::Release);drop(permit);Ok(())}
 pub fn shutdown(&self,timeout:Duration)->Result<(),String>{self.stopping.store(true,Ordering::Release);let deadline=Instant::now()+timeout;drop(lock_until(&self.admission,deadline,"admission")?);loop{let done=self.invocations.load(Ordering::Acquire)==0&&lock_until(&self.workers,deadline,"worker registry")?.iter().all(|w|w.is_finished());if done{break}if Instant::now()>=deadline{return Err("scheduler workers or invocations still active; shutdown unconfirmed".into())}thread::sleep(Duration::from_millis(5))}let mut workers=lock_until(&self.workers,deadline,"worker registry")?;let mut joins_failed=false;for worker in workers.drain(..){if worker.join().is_err(){joins_failed=true}}drop(workers);if joins_failed{self.join_failed.store(true,Ordering::Release)}if self.join_failed.load(Ordering::Acquire){return Err("worker join failed; outcome unconfirmed".into())}let pending=lock_until(&self.state,deadline,"analysis state")?.has_pending();let mut errors=lock_until(&self.errors,deadline,"scheduler errors")?;if pending&&!errors.iter().any(|e|e=="pending work retained at shutdown"){errors.push("pending work retained at shutdown".into())}if joins_failed{errors.push("worker join failed; outcome unknown".into())}if !errors.is_empty(){return Err(format!("scheduler errors: {}",errors.join("; ")))}Ok(())}
}
#[cfg(test)]mod tests{
use super::*;use serde_json::json;use std::{collections::HashMap,sync::mpsc::{Sender,Receiver}};
fn demo(c:&str)->Value{json!({"checksum":c,"filePath":format!("{c}.dem"),"mapName":"m","source":"ebot"})}
struct Fake{scheduler:Arc<Scheduler>,started:Receiver<String>,release:HashMap<String,Sender<()>>,state:Arc<Mutex<Analyses>>}
fn fixture(limit:usize,names:&[&str])->Fake{let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let(tx,rx)=mpsc::channel();let mut release=HashMap::new();let mut pending=HashMap::new();for &name in names{let(t,r)=mpsc::channel();release.insert(name.to_string(),t);pending.insert(name.to_string(),r);}let pending=Arc::new(Mutex::new(pending));let scheduler=Scheduler::new(state.clone(),order,move||Ok(json!({"analyze":{"maxConcurrentAnalyses":limit,"analyzePositions":false}})),move|claim,_|{let name=claim.analysis["demoChecksum"].as_str().unwrap().to_owned();let r=pending.lock().unwrap().remove(&name).unwrap();tx.send(name).unwrap();r.recv().map_err(|e|e.to_string())},|_|Ok(()));Fake{scheduler,started:rx,release,state}}
#[test]fn disconnect_blocks_new_work_and_waits_for_existing_writer_then_resume(){let f=fixture(1,&["a","b"]);let s=f.scheduler.clone();let caller=thread::spawn(move||s.add_renderer(vec![demo("a"),demo("b")]));assert_eq!(f.started.recv_timeout(Duration::from_secs(2)).unwrap(),"a");let s=f.scheduler.clone();let(tx,rx)=mpsc::channel();let disconnect=thread::spawn(move||tx.send(s.quiesce(Duration::from_secs(2))).unwrap());let deadline=Instant::now()+Duration::from_secs(1);while !f.scheduler.paused.load(Ordering::Acquire){assert!(Instant::now()<deadline);thread::yield_now();}assert!(f.scheduler.add_renderer(vec![demo("c")]).unwrap_err().contains("disconnected"));assert!(rx.recv_timeout(Duration::from_millis(100)).is_err());assert!(f.started.try_recv().is_err());f.release["a"].send(()).unwrap();rx.recv_timeout(Duration::from_secs(2)).unwrap().unwrap();disconnect.join().unwrap();caller.join().unwrap().unwrap();assert!(f.state.lock().unwrap().has_pending());assert!(f.started.try_recv().is_err());f.scheduler.resume(Duration::from_secs(1)).unwrap();assert_eq!(f.started.recv_timeout(Duration::from_secs(2)).unwrap(),"b");f.release["b"].send(()).unwrap();f.scheduler.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn quiesce_join_failure_stays_unconfirmed_on_retry(){let f=fixture(0,&[]);let job=thread::spawn(||panic!("untracked worker failure"));while !job.is_finished(){thread::yield_now()}f.scheduler.workers.lock().unwrap().push(job);assert!(f.scheduler.quiesce(Duration::from_secs(1)).unwrap_err().contains("join failed"));assert!(f.scheduler.quiesce(Duration::from_secs(1)).unwrap_err().contains("join failed"));assert!(f.scheduler.shutdown(Duration::from_secs(1)).unwrap_err().contains("join failed"));}
#[test]fn disconnect_admission_timeout_still_closes_future_admission(){let f=fixture(1,&[]);let guard=f.scheduler.admission.lock().unwrap();assert!(f.scheduler.quiesce(Duration::from_millis(40)).is_err());assert!(f.scheduler.paused.load(Ordering::Acquire));drop(guard);assert!(f.scheduler.add_renderer(vec![demo("x")]).unwrap_err().contains("disconnected"));f.scheduler.quiesce(Duration::from_secs(1)).unwrap();f.scheduler.shutdown(Duration::from_secs(1)).unwrap();}
#[test]fn resume_failure_keeps_admission_closed(){let f=fixture(1,&[]);f.scheduler.quiesce(Duration::from_secs(1)).unwrap();let state=f.state.clone();let _=thread::spawn(move||{let _guard=state.lock().unwrap();panic!("poison state for resume")}).join();assert!(f.scheduler.resume(Duration::from_secs(1)).unwrap_err().contains("resume state poisoned"));assert!(f.scheduler.paused.load(Ordering::Acquire));assert!(f.scheduler.add_renderer(vec![demo("b")]).unwrap_err().contains("disconnected"));}
#[test]fn disconnect_timeout_keeps_admission_closed_until_quiescent(){let f=fixture(1,&["a"]);let s=f.scheduler.clone();let caller=thread::spawn(move||s.add_renderer(vec![demo("a")]));f.started.recv_timeout(Duration::from_secs(2)).unwrap();assert!(f.scheduler.quiesce(Duration::from_millis(50)).unwrap_err().contains("unconfirmed"));assert!(f.scheduler.add_renderer(vec![demo("b")]).unwrap_err().contains("disconnected"));f.release["a"].send(()).unwrap();caller.join().unwrap().unwrap();f.scheduler.quiesce(Duration::from_secs(2)).unwrap();f.scheduler.resume(Duration::from_secs(1)).unwrap();f.scheduler.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn original_race_returns_while_other_worker_runs(){let f=fixture(2,&["a","b"]);let s=f.scheduler.clone();let(done_tx,done_rx)=mpsc::channel();let task=thread::spawn(move||{let r=s.add_renderer(vec![demo("a"),demo("b")]);done_tx.send(r).unwrap()});let a=f.started.recv_timeout(Duration::from_secs(2)).unwrap();let b=f.started.recv_timeout(Duration::from_secs(2)).unwrap();assert_ne!(a,b);f.release[&a].send(()).unwrap();done_rx.recv_timeout(Duration::from_secs(2)).unwrap().unwrap();assert!(f.state.lock().unwrap().all().len()==1);assert!(f.scheduler.shutdown(Duration::from_millis(50)).is_err());f.release[&b].send(()).unwrap();task.join().unwrap();f.scheduler.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn original_full_capacity_returns_while_pending(){let f=fixture(1,&["a","b"]);let s=f.scheduler.clone();let task=thread::spawn(move||s.add_renderer(vec![demo("a")]));assert_eq!(f.started.recv_timeout(Duration::from_secs(2)).unwrap(),"a");let s=f.scheduler.clone();let (tx,rx)=mpsc::channel();let second=thread::spawn(move||tx.send(s.add_renderer(vec![demo("b")])).unwrap());rx.recv_timeout(Duration::from_secs(2)).unwrap().unwrap();assert!(f.state.lock().unwrap().has_pending());f.release["a"].send(()).unwrap();assert_eq!(f.started.recv_timeout(Duration::from_secs(2)).unwrap(),"b");f.release["b"].send(()).unwrap();task.join().unwrap().unwrap();second.join().unwrap();f.scheduler.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn original_zero_capacity_returns_while_pending(){let f=fixture(0,&[]);f.scheduler.add_renderer(vec![demo("a")]).unwrap();assert!(f.state.lock().unwrap().has_pending());f.state.lock().unwrap().remove(&["a"]);f.scheduler.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn refill_rereads_snapshot_then_races_only_new_workers(){let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let limit=Arc::new(AtomicUsize::new(1));let l=limit.clone();let(tx,rx)=mpsc::channel();let mut release=HashMap::new();let mut pending=HashMap::new();for name in ["a","b","c"]{let(t,r)=mpsc::channel();release.insert(name.to_string(),t);pending.insert(name.to_string(),r);}let pending=Arc::new(Mutex::new(pending));let s=Scheduler::new(state,order,move||Ok(json!({"analyze":{"maxConcurrentAnalyses":l.load(Ordering::Acquire),"analyzePositions":false}})),move|claim,snapshot|{let name=claim.analysis["demoChecksum"].as_str().unwrap().to_owned();let r=pending.lock().unwrap().remove(&name).unwrap();tx.send((name,snapshot["analyze"]["maxConcurrentAnalyses"].as_u64().unwrap())).unwrap();r.recv().map_err(|e|e.to_string())},|_|Ok(()));let s2=s.clone();let(done,completed)=mpsc::channel();let caller=thread::spawn(move||done.send(s2.add_renderer(vec![demo("a"),demo("b"),demo("c")])).unwrap());assert_eq!(rx.recv_timeout(Duration::from_secs(2)).unwrap(),("a".into(),1));limit.store(2,Ordering::Release);release["a"].send(()).unwrap();let x=rx.recv_timeout(Duration::from_secs(2)).unwrap();let y=rx.recv_timeout(Duration::from_secs(2)).unwrap();assert_eq!(x.1,2);assert_eq!(y.1,2);release[&x.0].send(()).unwrap();completed.recv_timeout(Duration::from_secs(2)).unwrap().unwrap();assert!(s.shutdown(Duration::from_millis(50)).is_err());release[&y.0].send(()).unwrap();caller.join().unwrap();s.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn worker_panic_is_latched_and_shutdown_remains_error(){let s=Scheduler::new(Arc::new(Mutex::new(Analyses::new())),Arc::new(Mutex::new(())),||Ok(json!({"analyze":{"maxConcurrentAnalyses":1}})),|_,_|panic!("test worker panic"),|_|Ok(()));let _=s.add_renderer(vec![demo("a")]);let e=s.shutdown(Duration::from_secs(2)).unwrap_err();assert!(e.contains("database outcome unknown"));assert!(s.shutdown(Duration::from_secs(2)).is_err());}
#[test]fn shutdown_worker_registry_contention_is_bounded_and_retryable(){let f=fixture(0,&[]);let guard=f.scheduler.workers.lock().unwrap();let start=Instant::now();let err=f.scheduler.shutdown(Duration::from_millis(100)).unwrap_err();assert!(err.contains("worker registry shutdown unconfirmed"));assert!(start.elapsed()<Duration::from_secs(2));drop(guard);f.scheduler.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn refill_claims_are_one_synchronous_batch(){let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let(first_enter,entered)=mpsc::channel();let(release,blocked)=mpsc::channel();let blocked=Mutex::new(blocked);let records=Arc::new(Mutex::new(Vec::new()));let events=records.clone();let gate=AtomicBool::new(false);let(start,started)=mpsc::channel();let mut channels=HashMap::new();let mut releases=HashMap::new();for name in ["a","b"]{let(t,r)=mpsc::channel();releases.insert(name.to_string(),t);channels.insert(name.to_string(),r);}let channels=Mutex::new(channels);let s=Scheduler::new(state.clone(),order,||Ok(json!({"analyze":{"maxConcurrentAnalyses":2}})),move|claim,_|{let name=claim.analysis["demoChecksum"].as_str().unwrap().to_string();let r=channels.lock().unwrap().remove(&name).unwrap();start.send(name).unwrap();r.recv().map_err(|e|e.to_string())},move|e|{let name=e["name"].as_str().unwrap().to_string();let checksum=e["payload"]["demoChecksum"].as_str().unwrap_or("").to_string();events.lock().unwrap().push((name.clone(),checksum.clone()));if name=="analysis-status-changed"&&checksum=="a"&&!gate.swap(true,Ordering::AcqRel){first_enter.send(()).unwrap();blocked.lock().unwrap().recv().unwrap()}Ok(())});let a=s.clone();let first=thread::spawn(move||a.add_renderer(vec![demo("a"),demo("b")]));entered.recv_timeout(Duration::from_secs(2)).unwrap();let b=s.clone();let(tx,rx)=mpsc::channel();let second=thread::spawn(move||tx.send(b.add_renderer(vec![demo("c")])).unwrap());assert!(rx.recv_timeout(Duration::from_millis(100)).is_err());release.send(()).unwrap();rx.recv_timeout(Duration::from_secs(2)).unwrap().unwrap();let got1=started.recv_timeout(Duration::from_secs(2)).unwrap();let got2=started.recv_timeout(Duration::from_secs(2)).unwrap();assert_ne!(got1,got2);let events=records.lock().unwrap();let b_started=events.iter().position(|e|e.0=="analysis-status-changed"&&e.1=="b").unwrap();let c_added=events.iter().rposition(|e|e.0=="demos-added-to-analyses").unwrap();assert!(b_started<c_added);drop(events);state.lock().unwrap().remove(&["c"]);releases[&got1].send(()).unwrap();first.join().unwrap().unwrap();releases[&got2].send(()).unwrap();second.join().unwrap();s.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn cli_enqueue_returns_before_owned_invocation_finishes(){let f=fixture(1,&["a"]);svc::cli_connected(&f.state,&f.scheduler.order,"client").unwrap();assert_eq!(f.scheduler.enqueue_cli("client",vec![demo("a")],None).unwrap(),(true,true));assert_eq!(f.started.recv_timeout(Duration::from_secs(2)).unwrap(),"a");assert!(f.scheduler.shutdown(Duration::from_millis(100)).is_err());f.release["a"].send(()).unwrap();f.scheduler.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn cli_stop_after_enqueue_latches_unscheduled_work(){let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let weak=Arc::new(std::sync::OnceLock::<std::sync::Weak<Scheduler>>::new());let w=weak.clone();let s=Scheduler::new(state.clone(),order.clone(),||Ok(json!({"analyze":{"maxConcurrentAnalyses":1}})),|_,_|Ok(()),move|e|{if e["name"]=="demos-added-to-analyses"{w.get().unwrap().upgrade().unwrap().stopping.store(true,Ordering::Release)}Ok(())});weak.set(Arc::downgrade(&s)).unwrap_or_else(|_|panic!("binding exists"));svc::cli_connected(&state,&order,"client").unwrap();let result=s.enqueue_cli("client",vec![demo("a")],None).unwrap_err();assert!(result.contains("work enqueued but scheduler start failed"));assert!(state.lock().unwrap().has_pending());assert!(s.shutdown(Duration::from_secs(1)).unwrap_err().contains("work enqueued but scheduler start failed"));}
#[test]fn renderer_delivery_failure_latches_retained_queue(){let state=Arc::new(Mutex::new(Analyses::new()));let s=Scheduler::new(state.clone(),Arc::new(Mutex::new(())),||Ok(json!({"analyze":{"maxConcurrentAnalyses":1}})),|_,_|Ok(()),|e|if e["name"]=="demos-added-to-analyses"{Err("event failed".into())}else{Ok(())});assert!(s.add_renderer(vec![demo("a")]).unwrap_err().contains("delivery failed"));assert!(state.lock().unwrap().has_pending());let e=s.shutdown(Duration::from_secs(1)).unwrap_err();assert!(e.contains("delivery failed"));assert!(e.contains("pending work retained"));}
#[test]fn settings_read_failure_latches_retained_queue(){let state=Arc::new(Mutex::new(Analyses::new()));let s=Scheduler::new(state.clone(),Arc::new(Mutex::new(())),||Err("settings unavailable".into()),|_,_|Ok(()),|_|Ok(()));assert!(s.add_renderer(vec![demo("a")]).unwrap_err().contains("settings unavailable"));assert!(state.lock().unwrap().has_pending());let e=s.shutdown(Duration::from_secs(1)).unwrap_err();assert!(e.contains("settings unavailable"));assert!(e.contains("pending work retained"));}
#[test]fn callback_finalization_and_scheduler_finalization_are_idempotent(){let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let st=state.clone();let ord=order.clone();let s=Scheduler::new(state.clone(),order,||Ok(json!({"analyze":{"maxConcurrentAnalyses":1}})),move|claim,_|svc::finish(&st,&ord,claim.run_id),|_|Ok(()));s.add_renderer(vec![demo("a")]).unwrap();assert!(state.lock().unwrap().all().is_empty());s.add_renderer(vec![demo("b")]).unwrap();assert!(state.lock().unwrap().all().is_empty());s.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn renderer_remove_admission_timeout_does_not_mutate(){let f=fixture(0,&[]);f.scheduler.add_renderer(vec![demo("a")]).unwrap();let permit=f.scheduler.admission.lock().unwrap();let start=Instant::now();let err=f.scheduler.remove_renderer(vec!["a".into()],Duration::from_millis(100)).unwrap_err();assert!(err.contains("could not acquire admission"));assert!(start.elapsed()<Duration::from_secs(2));assert!(f.state.lock().unwrap().has_pending());drop(permit);f.scheduler.remove_renderer(vec!["a".into()],Duration::from_secs(1)).unwrap();assert!(!f.state.lock().unwrap().has_pending());f.scheduler.shutdown(Duration::from_secs(1)).unwrap();}
#[test]fn renderer_remove_cannot_interleave_claim_batch(){let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let(first_enter,entered)=mpsc::channel();let(release,blocked)=mpsc::channel();let blocked=Mutex::new(blocked);let records=Arc::new(Mutex::new(Vec::new()));let events=records.clone();let gate=AtomicBool::new(false);let(start,started)=mpsc::channel();let mut channels=HashMap::new();let mut releases=HashMap::new();for name in ["a","b"]{let(t,r)=mpsc::channel();releases.insert(name.to_string(),t);channels.insert(name.to_string(),r);}let channels=Mutex::new(channels);let s=Scheduler::new(state,order,||Ok(json!({"analyze":{"maxConcurrentAnalyses":2}})),move|claim,_|{let name=claim.analysis["demoChecksum"].as_str().unwrap().to_string();let r=channels.lock().unwrap().remove(&name).unwrap();start.send(name).unwrap();r.recv().map_err(|e|e.to_string())},move|e|{let name=e["name"].as_str().unwrap().to_string();let checksum=e["payload"]["demoChecksum"].as_str().unwrap_or("").to_string();events.lock().unwrap().push((name.clone(),checksum.clone()));if name=="analysis-status-changed"&&checksum=="a"&&!gate.swap(true,Ordering::AcqRel){first_enter.send(()).unwrap();blocked.lock().unwrap().recv().unwrap()}Ok(())});let a=s.clone();let first=thread::spawn(move||a.add_renderer(vec![demo("a"),demo("b")]));entered.recv_timeout(Duration::from_secs(2)).unwrap();let b=s.clone();let(tx,rx)=mpsc::channel();let remove=thread::spawn(move||tx.send(b.remove_renderer(vec!["b".into()],Duration::from_secs(2))).unwrap());assert!(rx.recv_timeout(Duration::from_millis(100)).is_err());release.send(()).unwrap();rx.recv_timeout(Duration::from_secs(2)).unwrap().unwrap();let got1=started.recv_timeout(Duration::from_secs(2)).unwrap();let got2=started.recv_timeout(Duration::from_secs(2)).unwrap();assert_ne!(got1,got2);let events=records.lock().unwrap();let b_started=events.iter().position(|e|e.0=="analysis-status-changed"&&e.1=="b").unwrap();let removed=events.iter().position(|e|e.0=="demos-removed-from-analyses").unwrap();assert!(b_started<removed);drop(events);releases[&got1].send(()).unwrap();first.join().unwrap().unwrap();releases[&got2].send(()).unwrap();remove.join().unwrap();s.shutdown(Duration::from_secs(2)).unwrap();}
#[test]fn renderer_remove_delivery_failure_is_latched(){let state=Arc::new(Mutex::new(Analyses::new()));let s=Scheduler::new(state.clone(),Arc::new(Mutex::new(())),||Ok(json!({"analyze":{"maxConcurrentAnalyses":0}})),|_,_|Ok(()),|event|if event["name"]=="demos-removed-from-analyses"{Err("remove push failed".into())}else{Ok(())});s.add_renderer(vec![demo("a")]).unwrap();let e=s.remove_renderer(vec!["a".into()],Duration::from_secs(1)).unwrap_err();assert!(e.contains("remove push failed"));assert!(!state.lock().unwrap().has_pending());assert!(s.shutdown(Duration::from_secs(1)).unwrap_err().contains("remove push failed"));}
}
#[cfg(test)]mod pg80_snapshot_tests{use super::*;use serde_json::json;
#[test]fn original_live_snapshot_pending_before_current(){let oracle:Value=serde_json::from_str(include_str!("../../tests/fixtures/pg80-original-analysis-snapshot.json")).unwrap();assert_eq!(oracle["sourceSha256"],"6a873183919d68038e0c7431b5aaf9f09d326e0ec4f7b3b628e2aa2dd346a383");let mut a=Analyses::new();let demos=["a","b","c","d"].into_iter().map(|id|json!({"checksum":id,"filePath":format!("C:\\owned\\{id}.dem"),"mapName":"de_mirage","source":"ebot"})).collect();a.add(demos,None,None,||"<time>".into()).unwrap();for _ in 0..2{let c=a.claim(2).unwrap();assert!(a.begin_claim(&c));a.set_running_status(c.run_id,"analyzing").unwrap();}let state=Arc::new(Mutex::new(a));let owner=Scheduler::new(state.clone(),Arc::new(Mutex::new(())),||Ok(json!({"analyze":{"maxConcurrentAnalyses":2}})),|_,_|Ok(()),|_|Ok(()));assert_eq!(owner.analysis_snapshot(Duration::from_secs(1)).unwrap(),oracle["before"].as_array().unwrap().clone());state.lock().unwrap().remove(&["c"]);let again=owner.analysis_snapshot(Duration::from_secs(1)).unwrap();assert_eq!(again.len(),3);assert_eq!(again[0]["demoChecksum"],"d");}
#[test]fn snapshot_state_contention_is_bounded(){let state=Arc::new(Mutex::new(Analyses::new()));let owner=Scheduler::new(state.clone(),Arc::new(Mutex::new(())),||Ok(json!({"analyze":{"maxConcurrentAnalyses":1}})),|_,_|Ok(()),|_|Ok(()));let guard=state.lock().unwrap();let now=Instant::now();assert!(owner.analysis_snapshot(Duration::from_millis(30)).is_err());assert!(now.elapsed()<Duration::from_secs(1));drop(guard);assert!(owner.analysis_snapshot(Duration::from_secs(1)).unwrap().is_empty());}
}
